CREATE OR REPLACE FUNCTION public.notification_next_allowed_at(p_user_id uuid, p_category text, p_priority text, p_requested_at timestamp with time zone DEFAULT clock_timestamp())
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_pref jsonb;
  v_requested timestamptz;
  v_min_priority text;
  v_quiet_start time;
  v_quiet_end time;
  v_timezone text;
  v_local timestamp;
  v_next_local timestamp;
begin
  if p_user_id is null then
    raise exception 'User ID is required';
  end if;

  if p_priority not in (
    'Low',
    'Normal',
    'High',
    'Urgent'
  ) then
    raise exception
      'Unsupported notification priority: %',
      p_priority;
  end if;

  v_requested := coalesce(
    p_requested_at,
    clock_timestamp()
  );

  v_pref :=
    public.notification_effective_preference(
      p_user_id,
      p_category
    );

  if not coalesce(
    (v_pref ->> 'notification_enabled')::boolean,
    true
  ) then
    return null;
  end if;

  v_min_priority := coalesce(
    nullif(v_pref ->> 'minimum_priority', ''),
    'Low'
  );

  if public.notification_priority_rank(p_priority)
     < public.notification_priority_rank(v_min_priority) then
    return null;
  end if;

  if not coalesce(
    (v_pref ->> 'quiet_hours_enabled')::boolean,
    true
  ) then
    return v_requested;
  end if;

  if p_priority = 'Urgent'
     and coalesce(
       (v_pref ->> 'urgent_bypass_enabled')::boolean,
       true
     ) then
    return v_requested;
  end if;

  v_quiet_start := coalesce(
    nullif(
      v_pref ->> 'quiet_hours_start',
      ''
    )::time,
    time '22:00'
  );

  v_quiet_end := coalesce(
    nullif(
      v_pref ->> 'quiet_hours_end',
      ''
    )::time,
    time '07:00'
  );

  v_timezone := coalesce(
    nullif(
      btrim(v_pref ->> 'timezone'),
      ''
    ),
    'Asia/Dhaka'
  );

  if not exists (
    select 1
    from pg_timezone_names tz
    where tz.name = v_timezone
  ) then
    raise exception
      'Unsupported notification timezone: %',
      v_timezone;
  end if;

  if v_quiet_start = v_quiet_end then
    return v_requested;
  end if;

  v_local := v_requested at time zone v_timezone;

  if v_quiet_start < v_quiet_end then
    if v_local::time >= v_quiet_start
       and v_local::time < v_quiet_end then
      v_next_local := v_local::date + v_quiet_end;
    else
      return v_requested;
    end if;
  else
    if v_local::time >= v_quiet_start then
      v_next_local :=
        (v_local::date + 1) + v_quiet_end;
    elsif v_local::time < v_quiet_end then
      v_next_local := v_local::date + v_quiet_end;
    else
      return v_requested;
    end if;
  end if;

  return v_next_local at time zone v_timezone;
end
$function$

CREATE OR REPLACE FUNCTION public.notification_open(p_notification_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_user_id uuid;
  v_notification public.notifications%rowtype;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'Authentication is required';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = v_user_id
      and p.is_active = true
  ) then
    raise exception using
      errcode = '42501',
      message = 'Active user profile is required';
  end if;

  if p_notification_id is null then
    raise exception using
      errcode = '22023',
      message = 'Notification ID is required';
  end if;

  select n.*
    into v_notification
  from public.notifications n
  where n.id = p_notification_id
    and n.recipient_user_id = v_user_id
  for update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'Notification not found';
  end if;

  if v_notification.status in (
    'Completed',
    'Dismissed',
    'Expired',
    'Cancelled'
  ) then
    return jsonb_build_object(
      'notification',
      to_jsonb(v_notification),
      'changed',
      false
    );
  end if;

  update public.notifications n
     set status = 'Actioned',
         read_at = coalesce(n.read_at, now()),
         opened_at = coalesce(n.opened_at, now()),
         actioned_at = coalesce(n.actioned_at, now()),
         snoozed_until = null
   where n.id = p_notification_id
     and n.recipient_user_id = v_user_id
   returning n.*
      into v_notification;

  return jsonb_build_object(
    'notification',
    to_jsonb(v_notification),
    'changed',
    true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.notification_priority_rank(p_priority text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE STRICT SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  case p_priority
    when 'Low' then
      return 1;
    when 'Normal' then
      return 2;
    when 'High' then
      return 3;
    when 'Urgent' then
      return 4;
    else
      raise exception using
        message = format(
          'Unsupported notification priority: %s',
          p_priority
        );
  end case;
end;
$function$

CREATE OR REPLACE FUNCTION public.notification_process_event_job(p_job_id bigint, p_worker_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_job public.notification_jobs%rowtype;
  v_event public.notification_events%rowtype;

  v_payload jsonb;
  v_preference jsonb;

  v_recipient uuid;
  v_notification_id uuid;

  v_category text;
  v_severity text;
  v_priority text;
  v_title text;
  v_message text;
  v_dedupe_key text;

  v_action_label text;
  v_action_route text;
  v_action_params jsonb;

  v_requested_at timestamptz;
  v_allowed_at timestamptz;
  v_expires_at timestamptz;
  v_status text;
begin
  if p_job_id is null then
    raise exception 'Job ID is required';
  end if;

  if nullif(
    btrim(coalesce(p_worker_id, '')),
    ''
  ) is null then
    raise exception 'Worker ID is required';
  end if;

  select *
  into v_job
  from public.notification_jobs
  where id = p_job_id
  for update;

  if v_job.id is null then
    raise exception
      'Notification job % does not exist',
      p_job_id;
  end if;

  if v_job.job_status <> 'Processing'
     or v_job.locked_by is distinct from btrim(p_worker_id) then
    raise exception
      'Job % is not Processing or is not owned by worker %',
      p_job_id,
      btrim(p_worker_id);
  end if;

  if v_job.job_type <> 'ProcessEvent'
     or v_job.event_id is null then
    raise exception
      'Job % is not a valid ProcessEvent job',
      p_job_id;
  end if;

  select *
  into v_event
  from public.notification_events
  where id = v_job.event_id
  for update;

  if v_event.id is null then
    perform public.notification_fail_job(
      p_job_id,
      p_worker_id,
      'Referenced notification event does not exist',
      interval '5 minutes'
    );

    return null;
  end if;

  if v_event.processing_status in (
    'Processed',
    'Ignored',
    'Cancelled'
  ) then
    perform public.notification_complete_job(
      p_job_id,
      p_worker_id
    );

    return null;
  end if;

  begin
    v_payload := coalesce(
      v_event.event_payload,
      '{}'::jsonb
    );

    if nullif(
      btrim(v_payload ->> 'recipient_user_id'),
      ''
    ) is null then
      raise exception
        'event_payload.recipient_user_id is required';
    end if;

    begin
      v_recipient :=
        (v_payload ->> 'recipient_user_id')::uuid;
    exception
      when invalid_text_representation then
        raise exception
          'event_payload.recipient_user_id must be a valid UUID';
    end;

    if not exists (
      select 1
      from public.profiles p
      where p.id = v_recipient
        and p.is_active = true
    ) then
      raise exception
        'Configured recipient is missing or inactive';
    end if;

    v_category := coalesce(
      nullif(
        btrim(v_payload ->> 'category'),
        ''
      ),
      'System'
    );

    v_severity := coalesce(
      nullif(
        btrim(v_payload ->> 'severity'),
        ''
      ),
      'Info'
    );

    if v_severity not in (
      'Info',
      'Success',
      'Warning',
      'Critical'
    ) then
      raise exception
        'Unsupported severity: %',
        v_severity;
    end if;

    v_priority := coalesce(
      nullif(
        btrim(v_payload ->> 'priority'),
        ''
      ),
      'Normal'
    );

    if v_priority not in (
      'Low',
      'Normal',
      'High',
      'Urgent'
    ) then
      raise exception
        'Unsupported priority: %',
        v_priority;
    end if;

    v_title :=
      nullif(btrim(v_payload ->> 'title'), '');

    v_message :=
      nullif(btrim(v_payload ->> 'message'), '');

    if v_title is null then
      raise exception
        'event_payload.title is required';
    end if;

    if v_message is null then
      raise exception
        'event_payload.message is required';
    end if;

    v_dedupe_key := coalesce(
      nullif(
        btrim(v_payload ->> 'dedupe_key'),
        ''
      ),
      'event:' || v_event.event_key
    );

    v_action_label :=
      nullif(
        btrim(v_payload ->> 'action_label'),
        ''
      );

    v_action_route :=
      nullif(
        btrim(v_payload ->> 'action_route'),
        ''
      );

    v_action_params := coalesce(
      v_payload -> 'action_params',
      '{}'::jsonb
    );

    if jsonb_typeof(v_action_params) <> 'object' then
      raise exception
        'event_payload.action_params must be a JSON object';
    end if;

    begin
      v_requested_at := coalesce(
        nullif(
          v_payload ->> 'scheduled_for',
          ''
        )::timestamptz,
        clock_timestamp()
      );
    exception
      when invalid_datetime_format then
        raise exception
          'event_payload.scheduled_for must be a valid timestamp';
    end;

    begin
      v_expires_at :=
        nullif(
          v_payload ->> 'expires_at',
          ''
        )::timestamptz;
    exception
      when invalid_datetime_format then
        raise exception
          'event_payload.expires_at must be a valid timestamp';
    end;

    if v_expires_at is not null
       and v_expires_at <= clock_timestamp() then
      raise exception
        'event_payload.expires_at must be in the future';
    end if;

    v_preference :=
      public.notification_effective_preference(
        v_recipient,
        v_category
      );

    v_allowed_at :=
      public.notification_next_allowed_at(
        v_recipient,
        v_category,
        v_priority,
        v_requested_at
      );

    if v_allowed_at is null then
      update public.notification_events
      set
        processing_status = 'Ignored',
        processed_at = clock_timestamp(),
        processing_error =
          'Suppressed by recipient notification preference'
      where id = v_event.id;

      perform public.notification_complete_job(
        p_job_id,
        p_worker_id
      );

      return null;
    end if;

    if v_expires_at is not null
       and v_allowed_at >= v_expires_at then
      update public.notification_events
      set
        processing_status = 'Ignored',
        processed_at = clock_timestamp(),
        processing_error =
          'Allowed delivery time is after notification expiry'
      where id = v_event.id;

      perform public.notification_complete_job(
        p_job_id,
        p_worker_id
      );

      return null;
    end if;

    v_status := case
      when v_allowed_at > clock_timestamp()
        then 'Scheduled'
      else 'Ready'
    end;

    update public.notification_events
    set
      processing_status = 'Processing',
      processed_at = null,
      processing_error = null
    where id = v_event.id;

    insert into public.notifications (
      event_id,
      recipient_user_id,
      category,
      severity,
      priority,
      title,
      message,
      entity_type,
      entity_id,
      employee_sys_id,
      project_id,
      action_label,
      action_route,
      action_params,
      status,
      scheduled_for,
      expires_at,
      dedupe_key,
      repeat_count,
      escalation_level
    )
    values (
      v_event.id,
      v_recipient,
      v_category,
      v_severity,
      v_priority,
      v_title,
      v_message,
      v_event.entity_type,
      v_event.entity_id,
      v_event.employee_sys_id,
      v_event.project_id,
      v_action_label,
      v_action_route,
      v_action_params,
      v_status,
      v_allowed_at,
      v_expires_at,
      v_dedupe_key,
      0,
      0
    )
    on conflict do nothing
    returning id
    into v_notification_id;

    if v_notification_id is null then
      select n.id
      into v_notification_id
      from public.notifications n
      where n.recipient_user_id = v_recipient
        and n.dedupe_key = v_dedupe_key
        and n.status in (
          'Scheduled',
          'Ready',
          'Delivered',
          'Read',
          'Actioned',
          'Snoozed',
          'Failed'
        )
      order by n.created_at desc
      limit 1;

      if v_notification_id is null then
        raise exception
          'Insert skipped but no open duplicate exists';
      end if;
    end if;

    update public.notification_events
    set
      processing_status = 'Processed',
      processed_at = clock_timestamp(),
      processing_error = null
    where id = v_event.id;

    perform public.notification_complete_job(
      p_job_id,
      p_worker_id
    );

    return v_notification_id;

  exception
    when others then
      update public.notification_events
      set
        processing_status = 'Failed',
        processed_at = null,
        processing_error = left(sqlerrm, 4000)
      where id = v_event.id;

      perform public.notification_fail_job(
        p_job_id,
        p_worker_id,
        sqlerrm,
        interval '5 minutes'
      );

      return null;
  end;
end
$function$

CREATE OR REPLACE FUNCTION public.notification_run_event_processor(p_worker_id text, p_batch_size integer DEFAULT 20, p_stale_after interval DEFAULT '00:15:00'::interval)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_worker_id text;
  v_recovered integer := 0;
  v_enqueued integer := 0;
  v_claimed integer := 0;
  v_processed integer := 0;
  v_completed integer := 0;
  v_failed integer := 0;
  v_ignored integer := 0;

  v_job public.notification_jobs%rowtype;
  v_notification_id uuid;
  v_event_status text;
begin
  v_worker_id :=
    nullif(btrim(coalesce(p_worker_id, '')), '');

  if v_worker_id is null then
    raise exception 'Worker ID is required';
  end if;

  if length(v_worker_id) > 200 then
    raise exception
      'Worker ID cannot exceed 200 characters';
  end if;

  if p_batch_size is null
     or p_batch_size < 1
     or p_batch_size > 100 then
    raise exception
      'Batch size must be between 1 and 100';
  end if;

  if p_stale_after is null
     or p_stale_after < interval '1 minute'
     or p_stale_after > interval '24 hours' then
    raise exception
      'Stale-lock interval must be between 1 minute and 24 hours';
  end if;

  v_recovered :=
    public.notification_recover_stale_jobs(
      p_stale_after
    );

  v_enqueued :=
    public.notification_enqueue_pending_events(
      p_batch_size
    );

  for v_job in
    with claimable as (
      select j.id
      from public.notification_jobs j
      where j.job_type = 'ProcessEvent'
        and j.job_status in ('Pending', 'Failed')
        and j.run_at <= clock_timestamp()
        and j.attempt_count < j.maximum_attempts
      order by j.run_at, j.id
      limit p_batch_size
      for update skip locked
    )
    update public.notification_jobs j
    set
      job_status = 'Processing',
      attempt_count = j.attempt_count + 1,
      locked_at = clock_timestamp(),
      locked_by = v_worker_id,
      started_at = clock_timestamp(),
      completed_at = null,
      failed_at = null,
      last_error = null
    from claimable c
    where j.id = c.id
    returning j.*
  loop
    v_claimed := v_claimed + 1;

    begin
      v_notification_id :=
        public.notification_process_event_job(
          v_job.id,
          v_worker_id
        );

      select e.processing_status
      into v_event_status
      from public.notification_events e
      where e.id = v_job.event_id;

      if v_event_status = 'Processed' then
        v_processed := v_processed + 1;
      elsif v_event_status = 'Ignored' then
        v_ignored := v_ignored + 1;
      elsif v_event_status = 'Failed' then
        v_failed := v_failed + 1;
      end if;

      if exists (
        select 1
        from public.notification_jobs j
        where j.id = v_job.id
          and j.job_status = 'Completed'
      ) then
        v_completed := v_completed + 1;
      elsif exists (
        select 1
        from public.notification_jobs j
        where j.id = v_job.id
          and j.job_status in ('Failed', 'DeadLetter')
      ) then
        v_failed := v_failed + 1;
      end if;

    exception
      when others then
        if exists (
          select 1
          from public.notification_jobs j
          where j.id = v_job.id
            and j.job_status = 'Processing'
            and j.locked_by = v_worker_id
        ) then
          perform public.notification_fail_job(
            v_job.id,
            v_worker_id,
            sqlerrm,
            interval '5 minutes'
          );
        end if;

        v_failed := v_failed + 1;
    end;
  end loop;

  return jsonb_build_object(
    'worker_id', v_worker_id,
    'stale_jobs_recovered', v_recovered,
    'events_enqueued', v_enqueued,
    'jobs_claimed', v_claimed,
    'jobs_completed', v_completed,
    'events_processed', v_processed,
    'events_ignored', v_ignored,
    'failures_observed', v_failed,
    'finished_at', clock_timestamp()
  );
end
$function$

CREATE OR REPLACE FUNCTION public.notification_run_server_processor(p_worker_id text DEFAULT NULL::text, p_batch_size integer DEFAULT 25, p_stale_after interval DEFAULT '00:15:00'::interval)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_worker_id text;
  v_started_at timestamptz;
  v_event_result jsonb;
  v_recurrence_result jsonb;
  v_delivery_result jsonb;
begin
  v_started_at := clock_timestamp();

  if p_batch_size is null
     or p_batch_size < 1
     or p_batch_size > 100 then
    raise exception
      'Batch size must be between 1 and 100';
  end if;

  if p_stale_after is null
     or p_stale_after < interval '1 minute'
     or p_stale_after > interval '24 hours' then
    raise exception
      'Stale-lock interval must be between 1 minute and 24 hours';
  end if;

  v_worker_id := nullif(
    btrim(coalesce(p_worker_id, '')),
    ''
  );

  if v_worker_id is null then
    v_worker_id :=
      'notification-processor:' ||
      pg_backend_pid()::text ||
      ':' ||
      to_char(
        v_started_at at time zone 'UTC',
        'YYYYMMDDHH24MISSMS'
      );
  end if;

  if length(v_worker_id) > 200 then
    raise exception
      'Worker ID cannot exceed 200 characters';
  end if;

  /*
   * Stage 1:
   * Recover stale locks, enqueue pending events,
   * claim due ProcessEvent jobs and process them.
   */
  v_event_result :=
    public.notification_run_event_processor(
      v_worker_id,
      p_batch_size,
      p_stale_after
    );

  /*
   * Stage 2:
   * Resolve completed workflow sources,
   * generate only configured bounded repeats/escalations.
   */
  v_recurrence_result :=
    public.notification_run_recurrence(
      p_batch_size
    );

  /*
   * Stage 3:
   * Promote due notifications and prepare
   * authoritative Inbox/Web Push delivery records.
   */
  v_delivery_result :=
    public.notification_prepare_deliveries(
      p_batch_size
    );

  return jsonb_build_object(
    'worker_id', v_worker_id,
    'batch_size', p_batch_size,
    'started_at', v_started_at,
    'event_processor', v_event_result,
    'recurrence_processor', v_recurrence_result,
    'delivery_processor', v_delivery_result,
    'finished_at', clock_timestamp()
  );
end
$function$

CREATE OR REPLACE FUNCTION public.notification_snooze(p_notification_id uuid, p_snoozed_until timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_user_id uuid;
  v_notification public.notifications%rowtype;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'Authentication is required';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = v_user_id
      and p.is_active = true
  ) then
    raise exception using
      errcode = '42501',
      message = 'Active user profile is required';
  end if;

  if p_notification_id is null then
    raise exception using
      errcode = '22023',
      message = 'Notification ID is required';
  end if;

  if p_snoozed_until is null then
    raise exception using
      errcode = '22023',
      message = 'Snooze time is required';
  end if;

  if p_snoozed_until <= now() then
    raise exception using
      errcode = '23514',
      message = 'Snooze time must be in the future';
  end if;

  select n.*
    into v_notification
  from public.notifications n
  where n.id = p_notification_id
    and n.recipient_user_id = v_user_id
  for update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'Notification not found';
  end if;

  if v_notification.status in (
    'Completed',
    'Dismissed',
    'Expired',
    'Cancelled'
  ) then
    raise exception using
      errcode = '23514',
      message = format(
        'Notification cannot be snoozed from status %s',
        v_notification.status
      );
  end if;

  update public.notifications n
     set status = 'Snoozed',
         snoozed_until = p_snoozed_until,
         scheduled_for = p_snoozed_until
   where n.id = p_notification_id
     and n.recipient_user_id = v_user_id
   returning n.*
      into v_notification;

  return jsonb_build_object(
    'notification',
    to_jsonb(v_notification),
    'changed',
    true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.notification_source_state(p_entity_type text, p_entity_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_type text;
  v_id bigint;
begin
  v_type := lower(
    btrim(
      coalesce(p_entity_type, '')
    )
  );

  if v_type = ''
     or nullif(
       btrim(coalesce(p_entity_id, '')),
       ''
     ) is null then
    return jsonb_build_object(
      'supported', false,
      'resolved', false,
      'state', 'Source reference unavailable'
    );
  end if;

  if p_entity_id !~ '^[0-9]+$' then
    return jsonb_build_object(
      'supported', false,
      'resolved', false,
      'state', 'Non-numeric source identifier'
    );
  end if;

  v_id := p_entity_id::bigint;

  begin
    if v_type in (
      'todo',
      'transfer',
      'exit'
    ) then
      return
        public.notification_check_core_source(
          v_type,
          v_id
        ) ||
        jsonb_build_object(
          'supported',
          true
        );

    elsif v_type = 'leave' then
      return
        public.notification_check_leave_source(
          v_id
        ) ||
        jsonb_build_object(
          'supported',
          true
        );

    elsif v_type in (
      'uniform_supply_order',
      'uniform_delivery_issue',
      'uniform_delivery_bill'
    ) then
      return
        public.notification_check_uniform_source(
          v_type,
          v_id
        ) ||
        jsonb_build_object(
          'supported',
          true
        );

    else
      return jsonb_build_object(
        'supported', false,
        'resolved', false,
        'state', 'Unsupported source type',
        'entity_type', v_type,
        'entity_id', p_entity_id
      );
    end if;

  exception
    when no_data_found then
      return jsonb_build_object(
        'supported', true,
        'resolved', false,
        'state', 'Source workflow record not found',
        'entity_type', v_type,
        'entity_id', p_entity_id
      );

    when sqlstate 'P0002' then
      return jsonb_build_object(
        'supported', true,
        'resolved', false,
        'state', 'Source workflow record not found',
        'entity_type', v_type,
        'entity_id', p_entity_id
      );
  end;
end
$function$

CREATE OR REPLACE FUNCTION public.notification_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_duplicate_active_uniform_employee()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.is_active and exists (
    select 1
    from public.uniform_order_employees uoe
    join public.uniform_supply_orders uo on uo.id = uoe.order_id
    where uoe.employee_id = new.employee_id
      and uoe.is_active = true
      and uoe.id <> coalesce(new.id, 0)
      and uo.status not in ('Completed', 'Cancelled')
  ) then
    raise exception 'Employee is already included in another active uniform order.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_terminal_uniform_delivery_items()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_parent_id bigint;
  v_status text;
begin
  v_parent_id := case when tg_op = 'DELETE' then old.delivery_id else new.delivery_id end;

  select o.status into v_status
  from public.uniform_deliveries d
  join public.uniform_supply_orders o on o.id = d.order_id
  where d.id = v_parent_id;

  if v_status in ('Completed', 'Cancelled') then
    raise exception 'Delivery items of a % uniform order are read-only.', lower(v_status);
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_terminal_uniform_employee_items()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_parent_id bigint;
  v_status text;
begin
  v_parent_id := case when tg_op = 'DELETE' then old.order_employee_id else new.order_employee_id end;

  select o.status into v_status
  from public.uniform_order_employees e
  join public.uniform_supply_orders o on o.id = e.order_id
  where e.id = v_parent_id;

  if v_status in ('Completed', 'Cancelled') then
    raise exception 'Item requirements of a % uniform order are read-only.', lower(v_status);
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_terminal_uniform_order_children()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
