  v_order_id bigint;
  v_status text;
begin
  v_order_id := case
    when tg_op = 'DELETE' then old.order_id
    else new.order_id
  end;

  select status into v_status
  from public.uniform_supply_orders
  where id = v_order_id;

  if v_status in ('Completed', 'Cancelled') then
