CREATE OR REPLACE FUNCTION public.protect_uniform_order_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.status in ('Completed', 'Cancelled') and new is distinct from old then
    raise exception 'A % uniform order is read-only.', lower(old.status);
  end if;

  if old.requisition_approved_at is not null
     and new.approved_sets is distinct from old.approved_sets then
    raise exception 'Approved set quantity cannot be changed after requisition approval.';
  end if;

  if old.order_number is distinct from new.order_number then
    raise exception 'Uniform order number cannot be changed.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.push_subscription_apply_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- A granted and active subscription cannot remain revoked.
  if new.is_active = true
     and new.permission_state = 'granted' then

    new.revoked_at := null;
  end if;

  -- Explicitly revoked or denied subscriptions become inactive.
  if new.permission_state in (
    'revoked',
    'denied',
    'unsupported'
  ) then
    new.is_active := false;

    new.revoked_at :=
      coalesce(
        new.revoked_at,
        case
          when tg_op = 'UPDATE'
            then old.revoked_at
          else null
        end,
        now()
      );
  end if;

  -- Inactive subscriptions receive a revocation timestamp.
  if new.is_active = false then
    new.revoked_at :=
      coalesce(
        new.revoked_at,
        case
          when tg_op = 'UPDATE'
            then old.revoked_at
          else null
        end,
        now()
      );
  end if;

  -- A successful delivery resets consecutive failure state.
  if tg_op = 'UPDATE'
     and new.last_success_at is distinct from
       old.last_success_at
     and new.last_success_at is not null then

    new.failure_count := 0;
  end if;

  -- Failure timestamps require a positive failure count.
  if new.last_failure_at is not null
     and new.failure_count < 1 then

    new.failure_count := 1;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.push_subscription_revoke(p_subscription_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_user_id uuid;
  v_subscription public.push_subscriptions%rowtype;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'Authentication is required';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = v_user_id
      and p.is_active = true
  ) then
    raise exception using
      errcode = '42501',
      message = 'Active user profile is required';
  end if;

  if p_subscription_id is null then
    raise exception using
      errcode = '22023',
      message = 'Subscription ID is required';
  end if;

  select s.*
  into v_subscription
  from public.push_subscriptions s
  where s.id = p_subscription_id
    and s.user_id = v_user_id
  for update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'Device subscription not found';
  end if;

  if v_subscription.is_active = false
     and v_subscription.permission_state = 'revoked' then
    return jsonb_build_object(
      'subscription_id', v_subscription.id,
      'is_active', v_subscription.is_active,
      'permission_state', v_subscription.permission_state,
      'revoked_at', v_subscription.revoked_at,
      'changed', false
    );
  end if;

  update public.push_subscriptions s
  set
    is_active = false,
    permission_state = 'revoked',
    revoked_at = coalesce(s.revoked_at, now())
  where s.id = p_subscription_id
    and s.user_id = v_user_id
  returning s.*
  into v_subscription;

  return jsonb_build_object(
    'subscription_id', v_subscription.id,
    'device_label', v_subscription.device_label,
    'is_active', v_subscription.is_active,
    'permission_state', v_subscription.permission_state,
    'revoked_at', v_subscription.revoked_at,
    'changed', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.push_subscription_update_device(p_subscription_id bigint, p_device_label text DEFAULT NULL::text, p_browser_name text DEFAULT NULL::text, p_platform_name text DEFAULT NULL::text, p_touch_last_seen boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_user_id uuid;
  v_subscription public.push_subscriptions%rowtype;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'Authentication is required';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = v_user_id
      and p.is_active = true
  ) then
    raise exception using
      errcode = '42501',
      message = 'Active user profile is required';
  end if;

  if p_subscription_id is null then
    raise exception using
      errcode = '22023',
      message = 'Subscription ID is required';
  end if;

  select s.*
  into v_subscription
  from public.push_subscriptions s
  where s.id = p_subscription_id
    and s.user_id = v_user_id
  for update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'Device subscription not found';
  end if;

  update public.push_subscriptions s
