        then s.platform_name
      else nullif(btrim(p_platform_name), '')
    end,

    last_seen_at = case
      when coalesce(p_touch_last_seen, true)
        then now()
      else s.last_seen_at
    end

  where s.id = p_subscription_id
    and s.user_id = v_user_id

  returning s.*
  into v_subscription;

  return jsonb_build_object(
    'subscription_id', v_subscription.id,
    'device_label', v_subscription.device_label,
    'browser_name', v_subscription.browser_name,
    'platform_name', v_subscription.platform_name,
    'permission_state', v_subscription.permission_state,
    'is_active', v_subscription.is_active,
    'last_seen_at', v_subscription.last_seen_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reactivate_employee(p_employee_sys_id bigint, p_new_join_date date, p_new_project text, p_remarks text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_employee public.employees%rowtype;
begin
  if p_employee_sys_id is null then
    raise exception using errcode = '22023', message = 'Employee system ID is required';
  end if;
  if p_new_join_date is null then
    raise exception using errcode = '23514', message = 'New join date is required';
  end if;
  if nullif(btrim(coalesce(p_new_project, '')), '') is null then
    raise exception using errcode = '23514', message = 'New project is required';
  end if;

  select * into v_employee
    from public.employees
   where id = p_employee_sys_id and deleted_at is null
   for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Employee not found';
  end if;
  if lower(btrim(coalesce(v_employee.status, ''))) = 'active' then
    raise exception using errcode = '23514', message = 'Employee is already Active';
  end if;

  update public.employees
     set status = 'Active',
         project_name = btrim(p_new_project),
         join_date = p_new_join_date,
         exit_date = null,
         exit_reason = null,
         updated_at = now()
   where id = p_employee_sys_id
   returning * into v_employee;

  update public.exits
     set status = 'Reactivated',
         completion_remarks = case
           when nullif(btrim(coalesce(p_remarks, '')), '') is null then completion_remarks
           when nullif(btrim(coalesce(completion_remarks, '')), '') is null then p_remarks
           else completion_remarks || E'\nReactivation: ' || p_remarks
         end
   where employee_sys_id = p_employee_sys_id
     and deleted_at is null
     and status = 'Completed';

  insert into public.activity_log (user_id, action, table_name, record_ref, detail)
  values (
    auth.uid(), 'reactivate', 'employees', p_employee_sys_id::text,
    format('Employee reactivated at %s%s', btrim(p_new_project),
      case when nullif(btrim(coalesce(p_remarks, '')), '') is null then '' else ': ' || p_remarks end)
  );

  return jsonb_build_object('employee', to_jsonb(v_employee));
end;
$function$

CREATE OR REPLACE FUNCTION public.reschedule_transfer(p_transfer_id bigint, p_new_effective_date date, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_transfer public.transfers%rowtype;
begin
  if p_new_effective_date is null then
    raise exception using errcode = '23514', message = 'New effective date is required';
  end if;

  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception using errcode = '23514', message = 'Reschedule reason is required';
  end if;

  select * into v_transfer
    from public.transfers
   where id = p_transfer_id
     and deleted_at is null
   for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'Transfer not found';
  end if;

  if v_transfer.status not in ('Scheduled', 'Joining Pending', 'Not Joined') then
    raise exception using errcode = '23514',
      message = format('Transfer cannot be rescheduled from status %s', v_transfer.status);
  end if;

  update public.transfers
     set previous_effective_date = effective_date,
         effective_date = p_new_effective_date,
         transfer_date = p_new_effective_date::text,
         status = case when p_new_effective_date <= current_date then 'Joining Pending' else 'Scheduled' end,
         rescheduled_at = now(),
         rescheduled_by = auth.uid(),
         not_joined_at = null,
         not_joined_by = null,
         not_joined_reason = null,
         not_joined_remarks = null,
         notes = case
           when nullif(btrim(coalesce(notes, '')), '') is null then 'Rescheduled: ' || p_reason
           else notes || E'\nRescheduled: ' || p_reason
         end,
         updated_at = now()
   where id = v_transfer.id
   returning * into v_transfer;

  insert into public.activity_log (user_id, action, table_name, record_ref, detail)
  values (
    auth.uid(), 'reschedule', 'transfers', v_transfer.id::text,
    format('Transfer rescheduled for employee system ID %s to %s: %s',
      v_transfer.employee_sys_id, p_new_effective_date, p_reason)
  );

  return to_jsonb(v_transfer);
end;
$function$

CREATE OR REPLACE FUNCTION public.save_uniform_delivery(p_order_id bigint, p_delivery_type text, p_delivery_date date, p_document_type text, p_document_number text, p_bill_amount numeric, p_remarks text DEFAULT NULL::text, p_items jsonb DEFAULT '[]'::jsonb, p_issues jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_order public.uniform_supply_orders%rowtype;
  v_delivery_id bigint;
  v_sequence integer;
  v_item jsonb;
  v_issue jsonb;
  v_allocation public.uniform_order_employees%rowtype;
  v_expected integer;
  v_previously_delivered integer;
  v_deliver_now integer;
  v_outstanding integer;
  v_total_remaining bigint;
  v_issue_count integer := 0;
  v_item_count integer := 0;
  v_new_status text;
begin
  if p_delivery_type not in ('Partial','Remaining','Full','Supplementary') then
    raise exception 'Invalid delivery type.';
  end if;
  if p_delivery_date is null then raise exception 'Delivery date is required.'; end if;
  if p_document_type not in ('Bill','Challan','Bill/Challan') then
    raise exception 'Invalid Bill/Challan document type.';
  end if;
  if btrim(coalesce(p_document_number,'')) = '' then
    raise exception 'Bill/Challan number is required.';
  end if;
  if coalesce(p_bill_amount,0) <= 0 then raise exception 'Bill amount must be greater than zero.'; end if;
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb)) <> 'array' then raise exception 'Delivery items must be a JSON array.'; end if;
  if jsonb_array_length(coalesce(p_items,'[]'::jsonb)) = 0 then raise exception 'At least one delivered item is required.'; end if;
  if jsonb_typeof(coalesce(p_issues,'[]'::jsonb)) <> 'array' then raise exception 'Delivery issues must be a JSON array.'; end if;

  select * into v_order from public.uniform_supply_orders where id=p_order_id for update;
  if not found then raise exception 'Uniform order does not exist.'; end if;
  if v_order.status in ('Completed','Cancelled') then raise exception 'This order is read-only.'; end if;
  if v_order.status not in ('Ready for Delivery','Partially Delivered') then
    raise exception 'Order must be Ready for Delivery or Partially Delivered.';
  end if;

  select coalesce(max(delivery_sequence),0)+1 into v_sequence
  from public.uniform_deliveries where order_id=p_order_id;

  -- Validate every line against the authoritative requirement and prior deliveries.
  for v_item in select value from jsonb_array_elements(p_items) loop
    v_deliver_now := coalesce((v_item->>'delivered_quantity')::integer,0);
    if v_deliver_now <= 0 then raise exception 'Delivered quantities must be positive integers.'; end if;

    select * into v_allocation
    from public.uniform_order_employees
    where id=(v_item->>'order_employee_id')::bigint
      and order_id=p_order_id and is_active=true;
    if not found then raise exception 'A delivery line references an invalid employee allocation.'; end if;

    if lower(v_item->>'item_name_snapshot')='shirt' then
      v_expected := v_allocation.set_quantity;
    elsif lower(v_item->>'item_name_snapshot')='pant' then
      v_expected := v_allocation.set_quantity;
    else
      select quantity into v_expected
      from public.uniform_order_employee_items
      where order_employee_id=v_allocation.id
        and item_id=(v_item->>'item_id')::bigint
        and coalesce(lower(btrim(size_text)),'')=coalesce(lower(btrim(v_item->>'size_text')),'')
      limit 1;
      if v_expected is null then raise exception 'A delivery line is not part of the employee requirement.'; end if;
    end if;

    select coalesce(sum(di.delivered_quantity),0) into v_previously_delivered
    from public.uniform_delivery_items di
    join public.uniform_deliveries d on d.id=di.delivery_id
    where d.order_id=p_order_id and d.status<>'Cancelled'
      and di.order_employee_id=v_allocation.id
      and lower(di.item_name_snapshot)=lower(v_item->>'item_name_snapshot')
      and coalesce(lower(btrim(di.size_text)),'')=coalesce(lower(btrim(v_item->>'size_text')),'');

    v_outstanding := greatest(v_expected-v_previously_delivered,0);
    if v_deliver_now > v_outstanding then
      raise exception 'Delivered quantity for % exceeds the outstanding quantity of %.', v_item->>'item_name_snapshot', v_outstanding;
    end if;
    v_item_count := v_item_count+1;
  end loop;

  insert into public.uniform_deliveries(order_id,delivery_sequence,delivery_type,delivery_date,status,remarks)
  values(p_order_id,v_sequence,p_delivery_type,p_delivery_date,
    case when jsonb_array_length(coalesce(p_issues,'[]'::jsonb))>0 then 'Received with Issues' else 'Received' end,
    nullif(btrim(coalesce(p_remarks,'')),'')
  ) returning id into v_delivery_id;

  for v_item in select value from jsonb_array_elements(p_items) loop
    insert into public.uniform_delivery_items(
      delivery_id,order_employee_id,item_id,item_name_snapshot,unit_snapshot,size_text,
      expected_quantity,delivered_quantity,remarks
    ) values(
      v_delivery_id,(v_item->>'order_employee_id')::bigint,
      nullif(v_item->>'item_id','')::bigint,v_item->>'item_name_snapshot',
      v_item->>'unit_snapshot',nullif(btrim(coalesce(v_item->>'size_text','')),''),
      (v_item->>'expected_quantity')::integer,(v_item->>'delivered_quantity')::integer,
      nullif(btrim(coalesce(v_item->>'remarks','')),'')
    );
  end loop;

  insert into public.uniform_delivery_bills(
    delivery_id,order_id,document_type,document_number,bill_amount,submission_date,remarks
  ) values(
    v_delivery_id,p_order_id,p_document_type,btrim(p_document_number),p_bill_amount,
    p_delivery_date,nullif(btrim(coalesce(p_remarks,'')),'')
  );

  for v_issue in select value from jsonb_array_elements(coalesce(p_issues,'[]'::jsonb)) loop
    if v_issue->>'issue_type' not in (
      'Short Quantity','Missing Item','Wrong Size','Damaged Item',
      'Modification Required','Returned','Replacement Pending','Other'
    ) then raise exception 'Invalid delivery issue type.'; end if;
    if btrim(coalesce(v_issue->>'remarks',''))='' then raise exception 'Issue remarks are required.'; end if;

    insert into public.uniform_delivery_issues(
      order_id,delivery_id,order_employee_id,item_id,issue_type,
      expected_quantity,received_quantity,affected_quantity,remarks,resolution_status
    ) values(
      p_order_id,v_delivery_id,nullif(v_issue->>'order_employee_id','')::bigint,
      nullif(v_issue->>'item_id','')::bigint,v_issue->>'issue_type',
      nullif(v_issue->>'expected_quantity','')::integer,
      nullif(v_issue->>'received_quantity','')::integer,
      nullif(v_issue->>'affected_quantity','')::integer,
      btrim(v_issue->>'remarks'),'Open'
    );
    v_issue_count := v_issue_count+1;
  end loop;

  -- Calculate the authoritative balance after this delivery.
  with required as (
    select e.id allocation_id,'Shirt' item_name,'' size_text,e.set_quantity qty
    from public.uniform_order_employees e where e.order_id=p_order_id and e.is_active and e.set_quantity>0
    union all
    select e.id,'Pant','',e.set_quantity
    from public.uniform_order_employees e where e.order_id=p_order_id and e.is_active and e.set_quantity>0
    union all
    select e.id,i.item_name_snapshot,coalesce(i.size_text,''),i.quantity
    from public.uniform_order_employees e
    join public.uniform_order_employee_items i on i.order_employee_id=e.id
    where e.order_id=p_order_id and e.is_active and i.quantity>0
  ), delivered as (
    select di.order_employee_id allocation_id,di.item_name_snapshot item_name,
      coalesce(di.size_text,'') size_text,sum(di.delivered_quantity) qty
    from public.uniform_delivery_items di
    join public.uniform_deliveries d on d.id=di.delivery_id
    where d.order_id=p_order_id and d.status<>'Cancelled'
    group by di.order_employee_id,di.item_name_snapshot,coalesce(di.size_text,'')
  )
  select coalesce(sum(greatest(r.qty-coalesce(d.qty,0),0)),0) into v_total_remaining
  from required r left join delivered d
    on d.allocation_id=r.allocation_id and lower(d.item_name)=lower(r.item_name)
    and lower(d.size_text)=lower(r.size_text);

  if p_delivery_type='Full' and v_total_remaining>0 then
    raise exception 'Full delivery cannot be saved because % item unit(s) remain outstanding.',v_total_remaining;
  end if;
  if p_delivery_type='Partial' and v_total_remaining=0 then
    raise exception 'Partial delivery is not valid because no quantity remains outstanding.';
  end if;

  v_new_status := case when v_total_remaining=0 then 'Delivered' else 'Partially Delivered' end;
  update public.uniform_supply_orders
  set status=v_new_status,
      final_delivery_at=case when v_total_remaining=0 then p_delivery_date else null end
  where id=p_order_id;

  return jsonb_build_object(
    'delivery_id',v_delivery_id,'delivery_sequence',v_sequence,
    'status',v_new_status,'remaining_quantity',v_total_remaining,
    'item_lines',v_item_count,'issues_created',v_issue_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_uniform_delivery_bill()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_order_id bigint;
  v_delivery_date date;
begin
  select order_id, delivery_date
    into v_order_id, v_delivery_date
  from public.uniform_deliveries
  where id = new.delivery_id;

  if v_order_id is null then
    raise exception 'Delivery record does not exist.';
  end if;

  if new.order_id <> v_order_id then
    raise exception 'Bill order does not match the selected delivery.';
  end if;

  if new.submission_date is null then
    new.submission_date := v_delivery_date;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_uniform_order_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_assigned bigint := 0;
  v_postponed bigint := 0;
  v_zero_set_without_items bigint := 0;
  v_open_issues bigint := 0;
  v_unpaid_bills bigint := 0;
  v_delivery_without_bill bigint := 0;
  v_deliveries bigint := 0;
begin
  if new.status = old.status then
    return new;
  end if;

  if new.status in (
    'Items Finalized','Requirements Submitted','Assigned to Supplier',
    'In Production','Ready for Delivery','Partially Delivered','Delivered','Completed'
  ) then
    select
      coalesce(sum(case when e.is_active then e.set_quantity else 0 end), 0),
      count(*) filter (
        where e.is_active = true
          and e.set_quantity = 0
          and not exists (
            select 1 from public.uniform_order_employee_items i
            where i.order_employee_id = e.id
          )
      )
    into v_assigned, v_zero_set_without_items
    from public.uniform_order_employees e
    where e.order_id = new.id;

    select coalesce(sum(p.set_quantity), 0)
      into v_postponed
    from public.uniform_order_postponements p
    where p.order_id = new.id
      and p.status in ('Open','Partially Activated');

    if v_assigned + v_postponed <> new.approved_sets then
      raise exception 'Assigned sets plus postponed sets must equal the approved set quantity.';
    end if;

    if v_zero_set_without_items > 0 then
      raise exception 'An employee with zero sets must have at least one additional item.';
    end if;
  end if;

  if new.status in (
    'Requirements Submitted','Assigned to Supplier','In Production','Ready for Delivery',
    'Partially Delivered','Delivered','Completed'
  ) and not exists (
    select 1 from public.uniform_requirement_reports r
    where r.order_id = new.id and r.is_current = true
  ) then
    raise exception 'A current requirement report is required before supplier assignment.';
  end if;

  if new.status in ('Partially Delivered','Delivered','Completed') then
    select count(*) into v_deliveries
    from public.uniform_deliveries d
    where d.order_id = new.id and d.status <> 'Cancelled';

    if v_deliveries = 0 then
      raise exception 'At least one delivery is required for this status.';
    end if;

    select count(*) into v_delivery_without_bill
    from public.uniform_deliveries d
    left join public.uniform_delivery_bills b on b.delivery_id = d.id
    where d.order_id = new.id
      and d.status <> 'Cancelled'
      and b.id is null;

    if v_delivery_without_bill > 0 then
      raise exception 'Every delivery must have a bill or challan.';
    end if;
  end if;

  if new.status = 'Completed' then
    if v_postponed > 0 then
      raise exception 'Postponed sets must be resolved before completion.';
    end if;

    select count(*) into v_open_issues
    from public.uniform_delivery_issues i
    where i.order_id = new.id
      and i.resolution_status in ('Open','In Progress');

    if v_open_issues > 0 then
      raise exception 'All delivery issues must be resolved before completion.';
    end if;

    select count(*) into v_unpaid_bills
    from public.uniform_delivery_bills b
    where b.order_id = new.id
      and (b.head_office_confirmed = false or b.paid = false);

    if v_unpaid_bills > 0 then
      raise exception 'All bills must be confirmed and paid before completion.';
    end if;

    if not exists (
      select 1 from public.uniform_delivery_bills b where b.order_id = new.id
    ) then
      raise exception 'At least one paid bill is required before completion.';
    end if;
  end if;

  return new;
end;
$function$
